#define ANARI_EXTENSION_UTILITY_IMPL
#include <anari/anari_cpp.hpp>
#include <anari/anari_cpp/ext/std.h>
#include <anari/ext/visrtx/makeVisRTXDevice.h>
#include <array>
#include <cstdio>
#include <string>

using vec2 = std::array<float, 2>;
using vec3 = std::array<float, 3>;
using uvec3 = std::array<unsigned int, 3>;
using uvec2 = std::array<unsigned int, 2>;

static void statusFunc(const void *, ANARIDevice, ANARIObject, ANARIDataType,
    ANARIStatusSeverity s, ANARIStatusCode, const char *m)
{ if (s <= ANARI_SEVERITY_WARNING) std::fprintf(stderr, "[anari] %s\n", m); }

static anari::Sampler makeSolidSampler(anari::Device d, vec3 texel)
{
  auto img = anari::newArray2D(d, ANARI_FLOAT32_VEC3, 1, 1);
  *anari::map<vec3>(d, img) = texel;
  anari::unmap(d, img);
  auto s = anari::newObject<anari::Sampler>(d, "image2D");
  anari::setAndReleaseParameter(d, s, "image", img);
  anari::setParameter(d, s, "inAttribute", "attribute0");
  anari::setParameter(d, s, "wrapMode1", "clampToEdge");
  anari::setParameter(d, s, "wrapMode2", "clampToEdge");
  anari::commitParameters(d, s);
  return s;
}

static bool centerChannelDominant(anari::Device d, anari::Frame frame,
    uvec2 size, int ch)
{
  anari::render(d, frame); anari::wait(d, frame);
  auto fb = anari::map<float>(d, frame, "channel.color");
  const float *px = fb.data + 4 * (size[0] * (size[1] / 2) + size[0] / 2);
  const int a = (ch + 1) % 3, b = (ch + 2) % 3;
  bool ok = px[ch] > 0.3f && px[ch] > px[a] + 0.1f && px[ch] > px[b] + 0.1f;
  if (!ok) std::printf("ch%d not dominant: (%.2f,%.2f,%.2f)\n",
      ch, px[0], px[1], px[2]);
  anari::unmap(d, frame, "channel.color");
  return ok;
}

int main()
{
  auto d = anari::Device(makeVisRTXDevice(statusFunc));

  // A document with a wired <image> driving base_color. The file input carries
  // no resolvable path; the bound sampler supplies the texels.
  const std::string xml =
      "<?xml version=\"1.0\"?>\n"
      "<materialx version=\"1.39\">\n"
      "  <image name=\"img1\" type=\"color3\">\n"
      "    <input name=\"file\" type=\"filename\" value=\"placeholder.png\"/>\n"
      "  </image>\n"
      "  <standard_surface name=\"srf\" type=\"surfaceshader\">\n"
      "    <input name=\"base_color\" type=\"color3\" nodename=\"img1\"/>\n"
      "  </standard_surface>\n"
      "  <surfacematerial name=\"M\" type=\"material\">\n"
      "    <input name=\"surfaceshader\" type=\"surfaceshader\" nodename=\"srf\"/>\n"
      "  </surfacematerial>\n"
      "</materialx>\n";

  auto mat = anari::newObject<anari::Material>(d, "materialx");
  anari::setParameter(d, mat, "sourceType", std::string("documentInline"));
  anari::setParameter(d, mat, "source", xml);

  // Property unavailable before the first commitParameters: param map not yet parsed.
  // Use ANARI_NO_WAIT so the commit buffer is not flushed before the check.
  {
    const char **pre = nullptr;
    if (anari::getProperty(d, mat, "textureInputs", pre, ANARI_NO_WAIT)) {
      std::printf("FAIL: textureInputs should be unavailable before first commit\n");
      return 1;
    }
  }

  auto green = makeSolidSampler(d, vec3{0.f, 1.f, 0.f});
  anari::setParameter(d, mat, "img1/file", green); // bind by MaterialX path
  anari::commitParameters(d, mat);

  const char **texInputs = nullptr;
  bool gotList = anari::getProperty(d, mat, "textureInputs", texInputs, ANARI_WAIT);
  bool listHasImg1File = false;
  if (gotList && texInputs)
    for (const char **p = texInputs; *p; ++p)
      if (std::string(*p) == "img1/file") listHasImg1File = true;
  if (!gotList || !listHasImg1File) {
    std::printf("FAIL: textureInputs missing img1/file (got=%d)\n", gotList);
    return 1;
  }

  std::array<vec3, 4> pos = {vec3{-1,-1,0}, {1,-1,0}, {1,1,0}, {-1,1,0}};
  std::array<vec2, 4> uv = {vec2{0,0}, {1,0}, {1,1}, {0,1}};
  std::array<uvec3, 2> idx = {uvec3{0,1,2}, uvec3{0,2,3}};
  auto geom = anari::newObject<anari::Geometry>(d, "triangle");
  anari::setParameterArray1D(d, geom, "vertex.position", pos.data(), pos.size());
  anari::setParameterArray1D(d, geom, "vertex.attribute0", uv.data(), uv.size());
  anari::setParameterArray1D(d, geom, "primitive.index", idx.data(), idx.size());
  anari::commitParameters(d, geom);

  auto surf = anari::newObject<anari::Surface>(d);
  anari::setAndReleaseParameter(d, surf, "geometry", geom);
  anari::setParameter(d, surf, "material", mat);
  anari::commitParameters(d, surf);
  auto world = anari::newObject<anari::World>(d);
  anari::setParameterArray1D(d, world, "surface", &surf, 1);
  anari::commitParameters(d, world);
  anari::release(d, surf);

  auto cam = anari::newObject<anari::Camera>(d, "perspective");
  anari::setParameter(d, cam, "position", vec3{0, 0, 3});
  anari::setParameter(d, cam, "direction", vec3{0, 0, -1});
  anari::setParameter(d, cam, "up", vec3{0, 1, 0});
  anari::commitParameters(d, cam);
  auto rnd = anari::newObject<anari::Renderer>(d, "default");
  anari::setParameter(d, rnd, "ambientRadiance", 1.f);
  anari::commitParameters(d, rnd);

  auto frame = anari::newObject<anari::Frame>(d);
  uvec2 size = {64, 64};
  anari::setParameter(d, frame, "size", size);
  anari::setParameter(d, frame, "channel.color", ANARI_FLOAT32_VEC4);
  anari::setParameter(d, frame, "world", world);
  anari::setParameter(d, frame, "camera", cam);
  anari::setParameter(d, frame, "renderer", rnd);
  anari::commitParameters(d, frame);

  const bool boundGreen = centerChannelDominant(d, frame, size, 1);

  // Rebind a different sampler to the SAME wired input: must rebind without a
  // retranscode (the texture_2d arg already exists). A spurious retranscode here
  // would re-run the splice path on "img1/file" and corrupt the graph.
  auto blue = makeSolidSampler(d, vec3{0.f, 0.f, 1.f});
  anari::setParameter(d, mat, "img1/file", blue);
  anari::commitParameters(d, mat);
  const bool reboundBlue = centerChannelDominant(d, frame, size, 2);

  // A third identical commit must not oscillate.
  anari::commitParameters(d, mat);
  const bool stable = centerChannelDominant(d, frame, size, 2);

  anari::release(d, green); anari::release(d, blue);
  anari::release(d, mat); anari::release(d, world);
  anari::release(d, cam); anari::release(d, rnd); anari::release(d, frame);
  anari::release(d, d);

  if (!boundGreen || !reboundBlue || !stable) {
    std::printf("FAIL: boundGreen=%d reboundBlue=%d stable=%d\n",
        boundGreen, reboundBlue, stable);
    return 1;
  }
  std::printf("PASS\n");
  return 0;
}

